List<String> calls = new ArrayList<>();
Mailer real = new Mailer();
Mailer spy = (Mailer) Proxy.newProxyInstance(
    Mailer.class.getClassLoader(), new Class<?>[]{Mailer.class},
    (proxy, method, args) -> {
      calls.add(method.getName());
      return method.invoke(real, args);        // forward to the real object
    });
new OrderService(spy).place(order);
assertThat(calls).containsExactly("send");
